def transforms(shape):
 # preserve coords normalized to bbox, 8 dihedral
 pts=list(shape); out=[]
 for f in range(8):
  arr=[]
  for r,c in pts:
   if f>=4: c=-c
   for _ in range(f%4): r,c=c,-r
   arr.append((r,c))
  mr=min(r for r,c in arr); mc=min(c for r,c in arr)
  norm={(r-mr,c-mc) for r,c in arr}
  if norm not in [x[1] for x in out]:out.append((f,norm))
 return out
